function applyBubbleTags(content,c,outcome){return (content||'').replace(/[[【]\s*换气泡\s*[|｜:：]\s*([^|｜\]】]*)\s*[|｜]\s*([^|｜\]】]*)\s*[|｜]\s*([^|｜\]】]*)(?:\s*[|｜]\s*([^\]】]*))?[\]】]/g,(m,bg,fg,shape,icon)=>{roleInterceptDiagnosticAction(outcome,bubbleRoleChange(c,bg,fg,shape,icon));return '';});}
//@@ private
function applyBubbleTags(content,c){return (content||'').replace(/[[【]\s*换气泡\s*[|｜:：]\s*([^|｜\]】]*)\s*[|｜]\s*([^|｜\]】]*)\s*[|｜]\s*([^|｜\]】]*)(?:\s*[|｜]\s*([^\]】]*))?[\]】]/g,(m,bg,fg,shape,icon)=>{bubbleRoleChange(c,bg,fg,shape,icon);return '';});}
