function bubbleNaturalRequest(text,c){text=''+(text||'');if(!/气泡/.test(text)||!/你(的|自己)|对方|ta|TA/.test(text)||!/换|改|设|用|弄|变/.test(text))return false;let bg='',fg='',shape='';
  const cm=text.match(/气泡(?:颜色)?[^，。；\n]{0,10}?(粉色|浅粉|深粉|红色|橙色|黄色|奶黄|绿色|薄荷|蓝色|浅蓝|深蓝|紫色|浅紫|白色|黑色|灰色|#[0-9a-fA-F]{6})/);if(cm)bg=cm[1];
  const fm=text.match(/(?:字体|文字)(?:颜色)?[^，。；\n]{0,10}?(粉色|浅粉|深粉|红色|橙色|黄色|奶黄|绿色|薄荷|蓝色|浅蓝|深蓝|紫色|浅紫|白色|黑色|灰色|#[0-9a-fA-F]{6})/);if(fm)fg=fm[1];
  const sm=text.match(/(原来方形|方形|直角|圆润|圆角|胶囊|很圆)/);if(sm)shape=sm[1];
  const im=text.match(/(爱心|星芒|星星|蝴蝶结|花瓣|小花|月光|月亮|不要图标|无图标)/);const icon=im?(im[1].includes('不要')||im[1].includes('无')?'无':im[1]):'';
  return (bg||fg||shape||icon)?bubbleRoleChange(c,bg,fg,shape,icon,true):false;}
function c_pin(id){const c=getC(id);c.pinned=!c.pinned;save();render();}
function isLover(c){if(!c||!isMain())return false;if(S.couple&&S.couple.cid===c.id)return true;return /恋人|男友|女友|男朋友|女朋友|老公|老婆|对象|未婚|爱人|情侣|伴侣|相恋|订婚|夫妻/.test((c.relation||'')+(c.persona||''));}
const FRIEND_REQ_DELAYS=[10000,20000,30000];
function friendRetryState(c,create){if(!c)return null;if(!c._friendReqRetry&&create)c._friendReqRetry={attempt:0,nextAt:0};return c._friendReqRetry||null;}
function friendRejectHistory(c){if(!c)return[];c._friendRejectHistory=Array.isArray(c._friendRejectHistory)?c._friendRejectHistory.filter(x=>x&&x.id&&+x.time).map(x=>({id:String(x.id),time:+x.time,attempt:Math.max(1,+x.attempt||1),msg:String(x.msg||'').slice(0,40)})).slice(-12):[];return c._friendRejectHistory;}
function friendRejectRemember(c,r){if(!c||!r)return null;const list=friendRejectHistory(c),old=list.find(x=>x.id===r.id);if(old)return old;const row={id:r.id,time:Date.now(),attempt:Math.max(1,+r.attempt||1),msg:friendReqText(r.msg,'想重新加回你')};list.push(row);c._friendRejectHistory=list.slice(-12);return row;}
function friendRequestUsedTexts(c){const out=friendRejectHistory(c).map(x=>x.msg);(S.friendRequests||[]).forEach(r=>{if(r&&c&&r.contactId===c.id&&r.msg)out.push(friendReqText(r.msg,''));});return new Set(out.map(friendReqNorm).filter(Boolean));}
function friendReqNorm(t){return String(t||'').replace(/[\s，。！？、,.!?~～…]/g,'').toLowerCase();}
function friendReqUnique(c,text,attempt){const used=friendRequestUsedTexts(c),raw=friendReqText(text,'');if(raw&&!used.has(friendReqNorm(raw)))return raw;const n=Math.max(1,+attempt||1),pool=['先别把话彻底堵死，给我一次解释的机会。','我知道你还在生气，但我不想就这样结束。','这是我第'+n+'次来找你，我还是想把话说清楚。','不逼你原谅，只想让你听完我该说的话。','微信联系不上你，我只能再认真申请一次。','你可以继续拒绝，但我不能装作什么都没发生。'];return pool.find(x=>!used.has(friendReqNorm(x)))||('第'+n+'次申请，我还是想和你说清楚。');}
function friendReaddPrompt(c){if(!c)return'';const h=friendRejectHistory(c),o=c.friendOrigin||{},wasReadd=o.kind==='readd'||!!friendMetaGet(c,'readdedAt')||h.length;if(!wasReadd)return'';const rejected=h.length,requests=h.map(x=>'第'+x.attempt+'次「'+x.msg+'」').join('；')||('「'+(o.requestMsg||'想重新加回你')+'」');return '\n\n# 拉黑、重新申请与通过后的持续记忆（自然模式也必须保留）\n'+S.me.name+'之前在微信拉黑过你。你为恢复联系主动发过好友申请'+(rejected?'，其中被明确拒绝过 '+rejected+' 次':'')+'；申请内容包括：'+requests+'。后来是'+S.me.name+'重新通过了你的申请。你清楚自己为什么申请回来，也记得拉黑前的关系与矛盾；不能把因果说反成“只是因为对方加我”，不能装作这段经历不存在。被问“为什么还加回来/为什么申请/被拒了几次”时，要按人设和这些真实经历直接回答。';}
function friendReaddInquiry(t){return /(?:为什么|怎么|干嘛|为何).{0,10}(?:加回来|加回|申请|重新加|又加)|(?:加回来|加回|重新申请).{0,10}(?:干什么|干嘛|为什么)|拒绝.{0,8}(?:几次|多少次)|记不记得.{0,12}(?:拉黑|申请|拒绝)/.test(String(t||'').replace(/\s+/g,''));}
function friendReaddReplyNeedsRepair(c,userText,content){if(!friendReaddInquiry(userText)||!friendReaddPrompt(c))return false;const t=String(content||'').replace(/\s+/g,'');return !t||/^(?:好|嗯|哦|不知道|不记得)[。.!！?？]?$/.test(t)||/(?:因为|就是因为).{0,5}(?:你|ta).{0,5}(?:加我|通过我)|你加我了/.test(t);}
