function friendRequestsInit(){S.friendRequests=Array.isArray(S.friendRequests)?S.friendRequests.filter(Boolean):[];const now=Date.now(),expired=[];S.friendRequests.forEach(r=>{const c=getC(r.contactId);r.kind=r.kind||(c&&friendMainBlocked(c)?'readd':'created');r.status=['pending','accepted','rejected'].includes(r.status)?r.status:'pending';r.time=+r.time||now;r.visibleAt=+r.visibleAt||r.time;r.source=r.source||(r.kind==='readd'?'重新添加':'角色资料');r.intent=r.intent||(c&&c.friendOrigin&&c.friendOrigin.intent)||'';if(r.status==='rejected'&&now-(+r.decidedAt||r.time)>=86400000)expired.push(r.id);if(r.status==='accepted'&&(!c||c.deleted))expired.push(r.id);});if(expired.length){const ids=new Set(expired),contacts=new Set(S.friendRequests.filter(r=>ids.has(r.id)).map(r=>r.contactId));S.friendRequests=S.friendRequests.filter(r=>!ids.has(r.id));contacts.forEach(id=>{const c=getC(id);if(c&&c._friendPending&&!S.friendRequests.some(r=>r.contactId===id&&(r.status==='pending'||r.status==='accepted'))){Object.keys(S.messages||{}).forEach(k=>{if(k===id||k.indexOf(id+'#')===0)delete S.messages[k];});S.contacts=S.contacts.filter(x=>x!==c);}});save();}friendDiscoveryState();return S.friendRequests;}
function queueFriendRequest(c,opt){if(!c)return null;opt=opt||{};friendRequestsInit();const kind=opt.kind||'created',old=S.friendRequests.find(r=>r.contactId===c.id&&r.kind===kind&&r.status==='pending');if(old)return old;const now=Date.now(),attempt=+opt.attempt||1,base=friendRequestReason(c,kind,opt),msg=kind==='readd'?friendReqUnique(c,base,attempt):base,req={id:uid(),contactId:c.id,kind,status:'pending',msg,source:opt.source||(kind==='readd'?'重新添加':'角色资料'),intent:opt.intent||(c.friendOrigin&&c.friendOrigin.intent)||'',time:now,visibleAt:now+Math.max(0,opt.delay==null?10000:+opt.delay||0),attempt,notified:false};S.friendRequests.push(req);save();return req;}
function friendRequestNotifyDue(initialized){if(!initialized)friendRequestsInit();const due=S.friendRequests.filter(r=>r.status==='pending'&&friendRequestVisible(r)&&!r.notified);if(!due.length)return;due.forEach(r=>{r.notified=true;});save();if(S.settings.sound)playDing();if(cur().p==='wechat'&&wxTab==='contacts'||cur().p==='newfriends')render();toast(due.length>1?'好友收到 '+due.length+' 条好友申请':'好友收到一条好友申请');}
function friendRequestSweep(){if(typeof document!=='undefined'&&document.hidden)return;const now=Date.now();friendRequestsInit();(S.contacts||[]).forEach(c=>{const st=friendRetryState(c,false);if(!st)return;if(!friendMainBlocked(c)){friendRetryClear(c);return;}if(st.nextAt&&now>=st.nextAt&&!S.friendRequests.some(r=>r.contactId===c.id&&r.status==='pending')){st.nextAt=0;save();createFriendRequest(c.id);}});friendRequestNotifyDue(true);wxNearbySweep(false);}
