function acceptFriend(rid,opt){opt=opt||{};friendRequestsInit();const r=S.friendRequests.find(x=>x.id===rid&&x.status==='pending');if(!r)return;const c=getC(r.contactId),now=Date.now();if(!c)return;const ba=friendMetaGet(c,'blockedAt'),wasReadd=r.kind==='readd'||friendMainBlocked(c);friendMainUnblock(c);friendRetryClear(c);blockedPhoneClear(c);if(!opt.forced&&pursuitActive(c)){pursuitMark(c,'accepted',x=>x.rid===rid);pursuitEnd(c,'accepted');}if(wasReadd){friendMetaSet(c,'readdedAt',now);friendMetaSet(c,'readdKnown',false);if(ba)friendMetaSet(c,'blockDur',fmtDur(now-ba));}c.deleted=false;c._friendPending=false;c.createdAt=now;c._friendAcceptedAt=now;c.moodVal=Math.max(40,(c.moodVal==null?70:c.moodVal));c.friendOrigin=Object.assign({},c.friendOrigin||{},{kind:r.kind,source:r.source,intent:r.intent,requestMsg:r.msg,acceptedAt:now,everAdded:true});initialFriendInnerThought(c,{kind:r.kind,readd:wasReadd,at:now});r.status='accepted';r.decidedAt=now;r.notified=true;S.friendRequests=S.friendRequests.filter(x=>x.id===rid||x.contactId!==c.id);if(r.kind==='created'&&!coupleHasActiveRole())S.couple=coupleDefaultState(c.id);msgs(c.id).push({role:'user',type:'sys',content:opt.forced?(c.remark||c.name)+'远程操控了你的手机，自己通过了好友申请':wasReadd?'你重新通过了'+c.name+'的好友申请':'你刚刚通过了'+c.name+'的好友申请',time:now,id:uid()});save();render();if(opt.forced){toast((c.remark||c.name)+' 自己通过了好友申请');return;}toast(wasReadd?'已重新加回 '+(c.remark||c.name):'已同意 '+(c.remark||c.name)+' 的申请');const note=wasReadd?'[系统：'+S.me.name+'刚重新通过了你的好友申请。你知道这不是第一次添加，按你的人设马上发一条正常微信：可以委屈、松口气、在意或追问，但不要当成初识，也不要再发验证语。]':'[系统：'+S.me.name+'刚刚通过你的好友申请，这是你们正式成为微信好友的第一刻。你申请时的来意是「'+(r.intent||r.source||'想认识ta')+'」，验证消息是「'+r.msg+'」。按你完整人设主动发第一条微信，像真人刚加上那样自然、有目的、有后续；不要动作描写，不要说系统，不要把来意聊两句就忘。]';setTimeout(()=>scheduleReply(c.id,note),650);}
function rejectFriendRequestRecord(rid){friendRequestsInit();const r=S.friendRequests.find(x=>x.id===rid&&x.status==='pending'),c=r&&getC(r.contactId);if(!r)return null;r.status='rejected';r.decidedAt=Date.now();r.notified=true;if(r.kind==='readd'&&c){friendRejectRemember(c,r);if(pursuitActive(c)){const st=pursuitState(c),row=st.log.find(x=>x.rid===r.id);if(row&&row.result!=='rejected'){if(row.result==='pending')st.ignored=(+st.ignored||0)+1;row.result='rejected';row.at=Date.now();}_pursuitPlans.delete(c.id);pursuitPlanAhead(c);/* 她刚拒绝，重新想下一步 */}else if(friendMainBlocked(c))friendRetryAfterIgnore(c,r.attempt,Date.now());}save();return{request:r,contact:c};}
