let _friendDiscoveryBusy=false;
function friendDiscoveryGenerate(test){if(_friendDiscoveryBusy)return;_friendDiscoveryBusy=true;try{const p=friendDiscoveryProfile(),now=Date.now(),c={id:cid(),name:p.name,avatar:p.avatar,remark:'',wxid:genWxid(),signature:p.signature,persona:p.persona,greeting:'',relation:p.relation,gender:p.gender,pinned:false,blocked:false,allowStrangerCall:true,allowStrangerSms:true,proactive:{enabled:false,start:9,end:23,times:2},chatBg:'',createdAt:now,deleted:true,_friendPending:true,friendOrigin:{kind:'surprise',source:p.source,intent:p.intent,requestMsg:p.msg,everAdded:false}};S.contacts.push(c);queueFriendRequest(c,{kind:'surprise',delay:test?800:3000+Math.floor(Math.random()*7000),source:p.source,intent:p.intent,msg:p.msg});if(!test){const d=friendDiscoveryState();d.n++;d.nextAt=now+d.freq*60000;}save();if(test){closeModal();toast('正在模拟申请，1秒内会收到通知');}}finally{_friendDiscoveryBusy=false;}}
function friendDiscoveryTest(){friendDiscoveryGenerate(true);}
function friendDiscoveryCheck(){const d=friendDiscoveryState(),day=todayStr(),now=Date.now();if(d.today!==day){d.today=day;d.n=0;d.nextAt=d.enabled?now+d.freq*60000:0;save();}if(!d.enabled||d.max<=0||d.n>=d.max)return;if(!d.nextAt){d.nextAt=now+d.freq*60000;save();return;}if(now>=d.nextAt)friendDiscoveryGenerate(false);}
