async function c_delete(id){const c=getC(id);
  if(!isMain()){if(!await uiConfirm('从当前小号「'+esc(S.me.name)+'」里删掉这个好友？\n（只影响这个小号，不动大号，之后还能搜微信号重新加回来）'))return;
    if(c._added)delete c._added[actId()];if(c._blk)delete c._blk[actId()];friendMetaClear(c);delete S.messages[mkey(id)];syncBlocks();save();stack.pop();render();toast('已从这个小号移除');return;}
  if(!await uiConfirm('删除这个角色？\n\n3天内可在「好友 → 好友找回」里恢复（连聊天记录一起回来）；超过3天才永久消失。'))return;c.deleted=true;c._delAt=Date.now();c._deleteCount=(c._deleteCount||0)+1;delete c._recoveredAt;/* 聊天记录先留着，找回时一并回来；3天后由 purgeOldDeleted 永久清掉 */
  friendRequestRemoveForContact(id);c._friendPending=false;
  if(S.couple){if(S.couple.gags)delete S.couple.gags[id];if(S.couple.gagAuth)S.couple.gagAuth=S.couple.gagAuth.filter(x=>x!==id);}// 删人时连带清掉对ta的禁言/授权,避免僵尸锁
  if(S.alter)Object.keys(S.alter).forEach(k=>{if(k.split('@').indexOf(id)>=0)delete S.alter[k];});// 清掉涉及ta的马甲聊天
  if(S.alterMeta)Object.keys(S.alterMeta).forEach(k=>{if(k.split('@').indexOf(id)>=0)delete S.alterMeta[k];});
  // 把这个被删角色的名字，从【别的角色】的记忆/登你微信记录/查手机数据里抹掉——免得别人还老提起ta（比如"我在你微信里看到了哥"）
  {const names=[c.name,c.remark].filter(Boolean);const hit=s=>names.some(n=>n&&n.length>=1&&(''+s).indexOf(n)>=0);
   S.contacts.forEach(o=>{if(o.id===id)return;
     if(o.memory)o.memory=o.memory.filter(m=>!hit(m));
     const wd=S.hisWx&&S.hisWx[o.id];if(wd&&wd.friends)wd.friends=wd.friends.filter(f=>!names.includes(f.name));
     const sp=S.spy&&S.spy[o.id];if(sp&&sp.wechat)sp.wechat=sp.wechat.filter(w=>!names.includes(w.who));
   });}
  if(c.proactive&&c.proactive.serverPush)companionRpc('phone_role_push_disable_profile',{p_target:cloudId(),p_owner_secret:companionOwnerSecret(),p_role_id:id}).catch(()=>{});
  save();stack.pop();render();}
function cleanStaleGags(){if(!S.couple||!S.couple.gags)return false;let ch=false,p=phoneFriendState();Object.keys(S.couple.gags).forEach(cid=>{if(cid.indexOf('pf:')===0){const id=cid.slice(3);if(!(p.friends||[]).some(f=>(''+(f.phone_id||f.id||'')).toUpperCase()===id)){delete S.couple.gags[cid];ch=true;}return;}if(cid.indexOf('pfg:')===0){const gid=cid.slice(4);if(!(p.groups||[]).some(g=>(g.group_id||g.id)===gid)){delete S.couple.gags[cid];ch=true;}return;}const c=getC(cid);if(!c||c.deleted){delete S.couple.gags[cid];ch=true;}});if(ch)save();return ch;}
function clearHistory(id){openModal(`<h3>清除聊天记录</h3>
  <button class="btn g" style="margin-bottom:8px" onclick="doClear('${id}','all')">清空全部文字聊天</button>
  <button class="btn g" style="margin-bottom:8px" onclick="doClear('${id}','old3d')">清除 3 天以前的旧聊天</button>
  <button class="btn g" style="margin-bottom:8px" onclick="doClear('${id}','old7d')">清除 7 天以前的旧聊天</button>
  <button class="btn g" style="margin-bottom:14px" onclick="doClear('${id}','keep200')">只保留最近 200 条</button>
  <div class="hint" style="margin-bottom:8px">上面几个清理旧聊天的选项会保护刚刚聊过的内容；通话记录始终保留。</div>
  <div class="hint">或按日期范围删除：</div>
  <div class="two"><div class="field"><label>从</label><input id="cl_a" type="date"></div><div class="field"><label>到</label><input id="cl_b" type="date"></div></div>
  <button class="btn d" onclick="doClear('${id}','range')">删除该范围</button>
  <button class="btn g" style="margin-top:8px" onclick="closeModal()">取消</button>`);}
function msgClearTime(m){const t=+(m&&(m.time||m.t));return t>946684800000?t:0;}
function protectedRecentMsgIndexes(list,n){const set=new Set();let seen=0;for(let i=list.length-1;i>=0&&seen<n;i--){if(list[i]&&list[i]._call)continue;set.add(i);seen++;}return set;}
async function doClear(id,mode){const list=msgs(id);let keep,tip='';
  // 通话记录【始终保留】，清空文字聊天不会动到电话/视频（去「通话记录」单独清）
  if(mode==='all'){keep=list.filter(m=>m._call);tip='清空全部文字聊天？通话记录会保留。';}
  else if(mode==='old3d'||mode==='old7d'){const days=mode==='old3d'?3:7,cut=Date.now()-days*86400000,guard=protectedRecentMsgIndexes(list,40);
    keep=list.filter((m,i)=>m._call||guard.has(i)||msgClearTime(m)>=cut);tip='删除 '+days+' 天以前的旧文字聊天？最近聊天和通话记录会保留。';}
  else if(mode==='keep200'){let seen=0;keep=[];for(let i=list.length-1;i>=0;i--){const m=list[i];if(m._call||seen<200){keep.push(m);if(!m._call)seen++;}}keep.reverse();tip='只保留最近 200 条文字聊天？更早的文字聊天会删除，通话记录保留。';}
  else{const a=$('#cl_a').value,b=$('#cl_b').value;if(!a||!b){toast('选好起止日期');return;}
    const t0=new Date(a+'T00:00:00').getTime(),t1=new Date(b+'T23:59:59').getTime();keep=list.filter(m=>{const t=msgClearTime(m);return m._call||!t||t<t0||t>t1;});tip='删除 '+a+' 到 '+b+' 的文字聊天？没有日期的旧消息和通话记录会保留。';}
  const n=list.length-keep.length;if(n<=0){toast('没有可删除的文字聊天');return;}if(!await uiConfirm(tip+'\n\n预计删除 '+n+' 条。'))return;
  const c=getC(id),aid=memoryScopeKey();summaryCursorRebaseAfterMessagePrune(c,aid,list,keep);S.messages[mkey(id)]=keep;await persistWechatMessagesNow();closeModal();render();toast('已删除 '+n+' 条文字聊天（通话记录保留）');}
function initiativeExpectedWakeAt(at,text){at=+at||Date.now();text=String(text||'');let m=text.match(/(?:睡|休息|眯)(?:个|一)?\s*(\d{1,2})\s*(分钟|小时)/);if(m)return at+Math.min(12*60,(+m[1]||1)*(m[2]==='小时'?60:1))*60000;if(/午睡|补觉|睡一会|眯一会/.test(text))return at+2*3600000;const d=new Date(at),h=d.getHours();if(h>=18){d.setDate(d.getDate()+1);d.setHours(8,0,0,0);return d.getTime();}if(h<6){d.setHours(8,0,0,0);return d.getTime();}return at+8*3600000;}
function initiativeUserAwayContext(c){if(!c)return{kind:'',text:'',at:0,until:0};const active=+(S.me&&S.me.sleep&&S.me.sleep.active)||0;if(active)return{kind:'sleep',text:'睡眠计时显示正在睡觉',at:active,until:initiativeExpectedWakeAt(active,'睡觉')};const m=[...msgs(c.id)].reverse().find(v=>v&&v.role==='user'&&v.type!=='sys'&&!v._call&&msgToText(v));if(!m)return{kind:'',text:'',at:0,until:0};const text=String(msgToText(m)||'').replace(/\s+/g,' ').trim(),at=msgClearTime(m)||0;if(!text||Date.now()-at>14*3600000||/我.{0,5}(醒了|起床了|回来了|忙完了|下班了)|(?:醒了|起来了|忙完了|回来了)$/.test(text))return{kind:'',text:'',at:0,until:0};if(!/睡不着|不睡|别睡|你.{0,5}睡|睡了吗/.test(text)&&/(?:我.{0,12}(?:去睡|睡觉|睡了|睡一会|补觉|午睡|休息)|(?:我先|我要|我去|我准备|我打算|我得|我该|困了.{0,6})(?:睡|休息)|晚安(?:啦|了)?$)/.test(text))return{kind:'sleep',text,at,until:initiativeExpectedWakeAt(at,text)};if(/(?:我.{0,16}(?:去忙|忙会|忙一下|工作|开会|上班|写作业|洗澡|吃饭|开车|收拾|办事|学习)|(?:我先|我要|我去|我得|我准备).{0,12}(?:忙|工作|开会|上班|写作业|洗澡|吃饭|开车|收拾|办事|学习))/.test(text))return{kind:'busy',text,at,until:0};return{kind:'',text:'',at:0,until:0};}
function initiativeAwayPrompt(c){const a=initiativeUserAwayContext(c);if(a.kind==='busy')return'\n对方最后明确交代了「'+a.text.slice(0,120)+'」。这段没回复有合理经过，禁止质问“为什么不理我/怎么不回”；可以自然问事情忙得怎么样、是否结束，或分享你自己的当下日常。';if(a.kind==='sleep')return a.until>Date.now()?'\n对方最后明确说去睡觉，预计仍在休息。现在必须保持安静，不能发消息、不能打电话，更不能问为什么不理你。':'\n对方之前明确说去睡觉，这段没回复是正常休息，不是故意冷落你。若此刻联系，只能自然承接睡醒后的生活，不能问为什么不回。';return'\n对方没有明确交代离开原因；你仍须按关系和人设判断，可以关心或分享日常，但不能默认对方故意冷落你。';}
